const Fixture& fixture_of(const char*name){for(unsigned int k=0;k<FIXTURE_COUNT;++k)if(std::strcmp(FIXTURES[k].name,name)==0)return FIXTURES[k];
 std::cerr<<"no fixture "<<name<<"\n";assert(false);return FIXTURES[0];}
void fixtures(){
 finals.assign(FIXTURE_COUNT,Final());
 for(unsigned int k=0;k<FIXTURE_COUNT;++k){const Fixture&f=FIXTURES[k];finals[k].ok=false;
  Bytes ram=base_ram(f.puts);State s=state_of(f.regs,f.entry,f.carry);Out o;
  if(f.error){reject(ram,s,f.stop,f.error);++error_count;continue;}
  if(!run(ram,s,f.stop,o)){std::cerr<<f.name<<"\n";assert(false);}
  const unsigned long long d=digest(ram,s,o.dev.bank_base,o.reads,o.status);
  if(!regs_equal(s,f.out)||s.pc!=f.stop||o.status!=ms5::AnimationMachineReturned||o.dev.bank_base!=0x200000||o.dev.pvc!=pvc_base()||
   !o.ports.empty()||o.reads!=0||d!=f.digest){
   std::cerr<<f.name<<" mismatch pc "<<std::hex<<s.pc<<" digest "<<d<<"\n";dump_regs(s,f.out);assert(false);}
  if(s.carry!=carry_of(f.c)){std::cerr<<f.name<<" carry "<<s.carry<<" want "<<f.c<<"\n";assert(false);}
  if(f.c)++kept_c;
  finals[k].ram=ram;finals[k].s=s;finals[k].ok=true;++success_count;}
}
const Final& final_of(const char*name){for(unsigned int k=0;k<FIXTURE_COUNT;++k)if(std::strcmp(FIXTURES[k].name,name)==0){assert(finals[k].ok);return finals[k];}
 std::cerr<<"no final "<<name<<"\n";assert(false);return finals[0];}
